lookup.day_rate:
// DOLE Handbook on Workers' Statutory Monetary Benefits 2024: monthly rate × 12 ÷ paid days a year, 313 or 261.
// proration_basis WORKING_DAYS: no statute fixes a basis for an incomplete month. Handbook ch.1 §I deducts "the wages corresponding
// to the days taken off", on "no work, no pay", so joiners, leavers and absences lose their own working days.
const terms = ctx.subject.employment.terms;
const unit = get(terms, 'rate.unit', 'MONTHLY');
const amount = Number(get(terms, 'rate.amount', 0));
const hours = Number(get(terms, 'normal_hours_per_day', ctx.lookup.normal_hours_per_day));
if (unit === 'DAILY') return amount;
if (unit === 'HOURLY' || unit === 'PIECE') return amount * hours;
const days = Number(get(ctx.subject.employment, 'employee_extension_data.days_per_year', ctx.lookup.days_per_year));
return (amount * ctx.lookup.months_per_year) / days;
